function maxTotalReward(rewardValues) {
  const values = [...new Set(rewardValues)].sort((a, b) => a - b);
  const largest = values[values.length - 1];
  const reachable = new Array(2 * largest).fill(false);
  reachable[0] = true;
  for (const value of values) {
    for (let total = value - 1; total >= 0; total--) {
      if (reachable[total]) {
        reachable[total + value] = true;
      }
    }
  }
  let best = 2 * largest - 1;
  while (!reachable[best]) {
    best--;
  }
  return best;
}

