function maxTotalReward(rewardValues) {
  // Try every legal sequence of picks directly, in any order the rule allows.
  const n = rewardValues.length;
  const used = new Array(n).fill(false);
  const explore = (x) => {
    let best = x;
    for (let i = 0; i < n; i++) {
      if (!used[i] && rewardValues[i] > x) {
        used[i] = true;
        best = Math.max(best, explore(x + rewardValues[i]));
        used[i] = false;
      }
    }
    return best;
  };
  return explore(0);
}

