function generate(rand, size) {
  if (size === 'large') {
    // Sometimes every value from 1 to 2000 once (the slowest case), otherwise 2000 random values.
    if (rand() < 0.3) {
      const values = Array.from({ length: 2000 }, (_, i) => i + 1);
      for (let i = values.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [values[i], values[j]] = [values[j], values[i]];
      }
      return [values];
    }
    const top = 300 + Math.floor(rand() * 1701);
    return [Array.from({ length: 2000 }, () => 1 + Math.floor(rand() * top))];
  }
  const n = 1 + Math.floor(rand() * 10);
  const top = [3, 10, 40, 2000][Math.floor(rand() * 4)];
  return [Array.from({ length: n }, () => 1 + Math.floor(rand() * top))];
}
